import sys

def main():
    s = sys.stdin.readline().strip()

    if not s:
        print(-1)
        return

    n = len(s)
    arr = [1 if c == '1' else 0 for c in s]

    total_ones = sum(arr)

    if total_ones == 0 or total_ones == n:
        print(-1)
        return

    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + arr[i]

    max_gain = 0
    best_a = -1
    best_b = -1

    for a in range(n):
        if arr[a] == 0:
            for b in range(a + 1, n):
                if arr[b] == 1:
                    gain = 1 - prefix_sum[b] + prefix_sum[a]
                    if gain > max_gain:
                        max_gain = gain
                        best_a = a
                        best_b = b

    if max_gain > 0:
        print(f"{best_a} {best_b}")
    else:
        print(-1)

if __name__ == "__main__":
    main()
